// Categorize students by course timeline
const enrollments = $input.all();
const now = new Date();
const results = {
  pre_course_7days: [],   // 7 days before
  pre_course_2days: [],   // 2 days before
  pre_course_1day: [],    // 1 day before
  course_day: [],         // Day of course
  post_course_1day: [],   // 1 day after
  post_course_7days: [],  // 7 days after
  post_course_30days: []  // 30 days after (alumni)
};

for (const enrollment of enrollments) {
  const data = enrollment.json;
  if (data.status !== 'active') continue;

  const courseDate = new Date(data.course_date);
  const diffMs = courseDate - now;
  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

  const studentInfo = {
    enrollment_id: data.enrollment_id,
    lead_id: data.lead_id,
    name: data.name,
    email: data.email,
    phone: data.phone,
    course_date: data.course_date,
    course_type: data.course_type,
    days_until_course: diffDays
  };

  if (diffDays === 7) results.pre_course_7days.push({ json: { ...studentInfo, trigger: 'pre_7days' } });
  if (diffDays === 2) results.pre_course_2days.push({ json: { ...studentInfo, trigger: 'pre_2days' } });
  if (diffDays === 1) results.pre_course_1day.push({ json: { ...studentInfo, trigger: 'pre_1day' } });
  if (diffDays === 0) results.course_day.push({ json: { ...studentInfo, trigger: 'course_day' } });
  if (diffDays === -1) results.post_course_1day.push({ json: { ...studentInfo, trigger: 'post_1day' } });
  if (diffDays === -7) results.post_course_7days.push({ json: { ...studentInfo, trigger: 'post_7days' } });
  if (diffDays === -30) results.post_course_30days.push({ json: { ...studentInfo, trigger: 'post_30days' } });
}

// Flatten all into one array with trigger type
const allActions = [
  ...results.pre_course_7days,
  ...results.pre_course_2days,
  ...results.pre_course_1day,
  ...results.course_day,
  ...results.post_course_1day,
  ...results.post_course_7days,
  ...results.post_course_30days
];

return allActions.length > 0 ? allActions : [{ json: { skip: true } }];

